def hit_counter(ops):
    from collections import deque
    hits = deque()
    out = []
    for op in ops:
        t = op[1]
        if op[0] == 'hit':
            hits.append(t)
        else:
            while hits and hits[0] <= t - 300:
                hits.popleft()
            out.append(len(hits))
    return out
